BEGIN;
UPDATE sign_in_experiences SET
  branding = '{"logoUrl": "data:image/png;base64,", "darkLogoUrl": "data:image/png;base64,", "favicon": "data:image/png;base64,"}'::jsonb,
  color = '{"primaryColor": "#2457EF", "isDarkModeEnabled": false, "darkPrimaryColor": "#6F93F7"}'::jsonb,
  language_info = '{"autoDetect": false, "fallbackLanguage": "zh-CN"}'::jsonb,
  custom_css = ':root, body, .logto_page-container {
  --color-bg-body: #f4f7fb;
  --color-bg-body-base: #f4f7fb;
  --color-bg-float: #ffffff;
  --color-bg-float-base: #ffffff;
  --color-bg-layer-1: #ffffff;
  --color-type-primary: #101827;
  --color-type-secondary: #516078;
  --color-line-border: #e0e6ef;
  --color-line-divider: #e0e6ef;
}
body, .logto_page-container { background: #f4f7fb !important; }
.logto_main-content {
  background: #ffffff !important;
  border: 1px solid #e0e6ef;
  border-radius: 18px !important;
  box-shadow: 0 18px 50px rgba(24, 48, 96, .10) !important;
}
.logto_branding-header img { height: 60px !important; max-width: 200px; }
.logto_branding-header [class*="headline"] {
  font-weight: 600;
  letter-spacing: .02em;
}
input { background: #ffffff !important; }
'
WHERE tenant_id = 'default' AND id = 'default';
INSERT INTO custom_phrases (tenant_id, id, language_tag, translation)
VALUES ('default', 'easelzhcn', 'zh-CN', '{"description": {"sign_in_to_your_account": "登录优创", "create_your_account": "注册优创账号"}}'::jsonb)
ON CONFLICT (tenant_id, language_tag) DO UPDATE SET translation = EXCLUDED.translation;
COMMIT;
